import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from './Layout';
import './EditJob.css'; // Utilise le même CSS pour garder une cohérence visuelle

function CreateJob() {
  const navigate = useNavigate();
  const [job, setJob] = useState({ 
    title: '', 
    company: '', 
    description: '',
    type: 'CDI' 
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/jobs`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json' 
        },
        body: JSON.stringify(job)
      });

      if (response.ok) {
        alert("Offre créée avec succès !");
        navigate('/');
      } else {
        const errorData = await response.text();
        alert("Erreur lors de la création : " + errorData);
      }
    } catch (error) {
      console.error("Erreur serveur :", error);
      alert("Erreur lors de la connexion au serveur");
    }
  };

  return (
    <Layout>
      <form onSubmit={handleSubmit} className="edit-job-form">
        <h2 className="edit-job-title">Créer une nouvelle offre</h2>
        
        <div className="form-group">
          <label>Titre :</label>
          <input 
            required
            value={job.title} 
            onChange={e => setJob({...job, title: e.target.value})} 
          />
        </div>

        <div className="form-group">
          <label>Entreprise :</label>
          <input 
            required
            value={job.company} 
            onChange={e => setJob({...job, company: e.target.value})} 
          />
        </div>

        <div className="form-group">
          <label>Description :</label>
          <textarea 
            required
            value={job.description} 
            onChange={e => setJob({...job, description: e.target.value})} 
          />
        </div>

        <div className="form-group">
          <label>Type :</label>
          <select value={job.type} onChange={e => setJob({...job, type: e.target.value})}>
            <option value="CDI">CDI</option>
            <option value="CDD">CDD</option>
            <option value="Stage">Stage</option>
          </select>
        </div>

        <button type="submit" className="btn-submit">Publier l'offre</button>
      </form>
    </Layout>
  );
}

export default CreateJob;
